package com.goat;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class GoatHuntingIdsTest
{
	@Test
	public void capacityScalesWithHunterLevel()
	{
		assertEquals(16, GoatHuntingIds.capacityForHunterLevel(60));
		assertEquals(16, GoatHuntingIds.capacityForHunterLevel(69));
		assertEquals(18, GoatHuntingIds.capacityForHunterLevel(70));
		assertEquals(18, GoatHuntingIds.capacityForHunterLevel(76));
		assertEquals(20, GoatHuntingIds.capacityForHunterLevel(77));
		assertEquals(20, GoatHuntingIds.capacityForHunterLevel(84));
		assertEquals(22, GoatHuntingIds.capacityForHunterLevel(85));
		assertEquals(22, GoatHuntingIds.capacityForHunterLevel(92));
		assertEquals(24, GoatHuntingIds.capacityForHunterLevel(93));
	}

	@Test
	public void levelsBelowTheActivityReturnMinimumCapacity()
	{
		assertEquals(GoatHuntingIds.MIN_CAPACITY, GoatHuntingIds.capacityForHunterLevel(1));
		assertEquals(GoatHuntingIds.MIN_CAPACITY, GoatHuntingIds.capacityForHunterLevel(59));
	}

	@Test
	public void goatPitActivityIdsUseGamevals()
	{
		assertTrue(GoatHuntingIds.isGoatPitObject(ObjectID.GOAT_PIT));
		assertTrue(GoatHuntingIds.isGoatPitObject(ObjectID.GOAT_PIT_MULTI_EMPTY));
		assertTrue(GoatHuntingIds.isGoatPitObject(ObjectID.GOAT_PIT_MULTI_SPIKES));
		assertTrue(GoatHuntingIds.isGoatPitObject(ObjectID.GOAT_PIT_MULTI_ONE));
		assertTrue(GoatHuntingIds.isGoatPitObject(ObjectID.GOAT_PIT_MULTI_SOME));
		assertTrue(GoatHuntingIds.isGoatPitObject(ObjectID.GOAT_PIT_MULTI_FULL));
		assertTrue(GoatHuntingIds.isSpikeSupplyObject(ObjectID.GOAT_PIT_SPIKES));
		assertTrue(GoatHuntingIds.isGoatPitGoat(NpcID.GOAT_PIT_GOAT));

		assertFalse(GoatHuntingIds.isGoatPitObject(ObjectID.GOAT_PIT_SPIKES));
		assertFalse(GoatHuntingIds.isSpikeSupplyObject(ObjectID.GOAT_PIT));
	}

	@Test
	public void telegrabRuneClassificationMatchesSpellRequirements()
	{
		assertTrue(GoatHuntingIds.isLawRune(ItemID.LAWRUNE));
		assertTrue(GoatHuntingIds.isAirRune(ItemID.AIRRUNE));
		assertTrue(GoatHuntingIds.isAirRune(ItemID.MISTRUNE));
		assertTrue(GoatHuntingIds.isAirRune(ItemID.DUSTRUNE));
		assertTrue(GoatHuntingIds.isAirRune(ItemID.SMOKERUNE));
		assertFalse(GoatHuntingIds.isAirRune(ItemID.WATERRUNE));
	}

	@Test
	public void airStavesProvideTheAirRune()
	{
		assertTrue(GoatHuntingIds.isAirStaff(ItemID.STAFF_OF_AIR));
		assertTrue(GoatHuntingIds.isAirStaff(ItemID.AIR_BATTLESTAFF));
		assertTrue(GoatHuntingIds.isAirStaff(ItemID.MYSTIC_AIR_STAFF));
		assertTrue(GoatHuntingIds.isAirStaff(ItemID.SMOKE_BATTLESTAFF));
		assertTrue(GoatHuntingIds.isAirStaff(ItemID.MIST_BATTLESTAFF));
		assertTrue(GoatHuntingIds.isAirStaff(ItemID.DUST_BATTLESTAFF));
		assertFalse(GoatHuntingIds.isAirStaff(ItemID.STAFF_OF_FIRE));
	}
}

package com.goat;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoatHuntingTrackerTest
{
	@Test
	public void namesMatchActivityObjects()
	{
		assertTrue(GoatHuntingTracker.matchesPitName("Goat pit"));
		assertTrue(GoatHuntingTracker.matchesPitName("Large goat pit"));
		assertTrue(GoatHuntingTracker.matchesSpikePileName("Pile of spikes"));
		assertTrue(GoatHuntingTracker.matchesSpikePileName("Spikes supply"));
		assertTrue(GoatHuntingTracker.matchesSpikePileName("Spike pile"));
		assertTrue(GoatHuntingTracker.matchesGoatName("Wyrmscraig Goat"));
	}

	@Test
	public void unrelatedNamesDoNotMatch()
	{
		assertFalse(GoatHuntingTracker.matchesPitName("Pit"));
		assertFalse(GoatHuntingTracker.matchesSpikePileName("Pile of stones"));
		assertFalse(GoatHuntingTracker.matchesSpikePileName("Spike"));
		assertFalse(GoatHuntingTracker.matchesGoatName("Sheep"));
	}
}

package com.goat;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TelegrabAvailabilityTest
{
	@Test
	public void telegrabRequiresLawRuneAndAirCoverage()
	{
		assertFalse(TelegrabAvailability.canCastWithCounts(0, 1, false));
		assertFalse(TelegrabAvailability.canCastWithCounts(1, 0, false));
		assertTrue(TelegrabAvailability.canCastWithCounts(1, 1, false));
		assertTrue(TelegrabAvailability.canCastWithCounts(1, 0, true));
	}
}

package com.goat;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoatPitStateTest
{
	@Test
	public void fullPitDependsOnCapacity()
	{
		assertTrue(new GoatPitState(16, true, 16).isFull());
		assertFalse(new GoatPitState(16, true, 24).isFull());
		assertTrue(new GoatPitState(24, true, 24).isFull());
	}

	@Test
	public void countAndCapacityAreClamped()
	{
		assertEquals(0, new GoatPitState(-1, true, 20).getCount());
		assertEquals(20, new GoatPitState(99, true, 20).getCount());
		assertEquals(GoatHuntingIds.MIN_CAPACITY, new GoatPitState(0, true, 0).getCapacity());
		assertEquals(GoatHuntingIds.MAX_CAPACITY, new GoatPitState(0, true, 99).getCapacity());
	}

	@Test
	public void unspikedPitNeedsSpikes()
	{
		assertTrue(new GoatPitState(0, false, 20).needsSpikes());
		assertFalse(new GoatPitState(0, true, 20).needsSpikes());
	}

	@Test
	public void labelShowsCountAndCapacity()
	{
		assertEquals("12 / 20", new GoatPitState(12, true, 20).label());
		assertEquals("16 / 16", new GoatPitState(99, true, 16).label());
	}
}

