package com.goat;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemVariationMapping;

@Singleton
class TelegrabAvailability
{
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1,
		VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4,
		VarbitID.RUNE_POUCH_TYPE_5,
		VarbitID.RUNE_POUCH_TYPE_6
	};

	private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1,
		VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4,
		VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6
	};

	@Inject
	private Client client;

	private boolean available;

	void refresh()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			available = false;
			return;
		}

		int lawRunes = countInventoryRunes(inventory, true) + countRunePouchRunes(inventory, true);
		int airRunes = countInventoryRunes(inventory, false) + countRunePouchRunes(inventory, false);
		available = canCastWithCounts(lawRunes, airRunes, hasAirStaff());
	}

	void clear()
	{
		available = false;
	}

	boolean isAvailable()
	{
		return available;
	}

	static boolean canCastWithCounts(int lawRunes, int airRunes, boolean airStaff)
	{
		return lawRunes > 0 && (airStaff || airRunes > 0);
	}

	private int countInventoryRunes(ItemContainer inventory, boolean law)
	{
		int total = 0;
		for (Item item : inventory.getItems())
		{
			if (matchesRune(item.getId(), law))
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	private int countRunePouchRunes(ItemContainer inventory, boolean law)
	{
		if (!hasRunePouch(inventory))
		{
			return 0;
		}

		EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		int total = 0;
		for (int i = 0; i < RUNE_POUCH_TYPE_VARBITS.length; i++)
		{
			int amount = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[i]);
			if (amount <= 0)
			{
				continue;
			}

			int runeId = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			if (runeId == 0)
			{
				continue;
			}

			if (matchesRune(runePouchEnum.getIntValue(runeId), law))
			{
				total += amount;
			}
		}
		return total;
	}

	private boolean hasAirStaff()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return false;
		}
		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		return weapon != null && GoatHuntingIds.isAirStaff(ItemVariationMapping.map(weapon.getId()));
	}

	private static boolean hasRunePouch(ItemContainer inventory)
	{
		return inventory.contains(ItemID.BH_RUNE_POUCH)
			|| inventory.contains(ItemID.BH_RUNE_POUCH_TROUVER)
			|| inventory.contains(ItemID.DIVINE_RUNE_POUCH)
			|| inventory.contains(ItemID.DIVINE_RUNE_POUCH_TROUVER);
	}

	private static boolean matchesRune(int itemId, boolean law)
	{
		return law ? GoatHuntingIds.isLawRune(itemId) : GoatHuntingIds.isAirRune(itemId);
	}
}

