import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Goat Hunting",
	description = "Highlights the Wyrmscraig Goat Hunting pit, spikes, spike piles, and telegrab-able goats!",
	tags = {"goat", "goats", "hunting", "hunter", "wyrmscraig"}
)
public class GoatHuntingPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private GoatHuntingOverlay overlay;

	@Inject
	private GoatHuntingTracker tracker;

	@Inject
	private TelegrabAvailability telegrabAvailability;

	private volatile boolean started;

	@Override
	protected void startUp()
	{
		started = true;
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (!started)
			{
				return;
			}
			telegrabAvailability.refresh();
			tracker.refreshState();
		});
	}

	@Override
	protected void shutDown()
	{
		started = false;
		overlayManager.remove(overlay);
		tracker.clear();
		telegrabAvailability.clear();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		tracker.onTileObjectSpawned(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		tracker.onTileObjectDespawned(event.getGameObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		tracker.onTileObjectSpawned(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		tracker.onTileObjectDespawned(event.getGroundObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		tracker.onTileObjectSpawned(event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		tracker.onTileObjectDespawned(event.getDecorativeObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		tracker.onTileObjectSpawned(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		tracker.onTileObjectDespawned(event.getWallObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		tracker.onNpcSpawned(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		tracker.onNpcDespawned(event.getNpc());
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (isRunePouchVarbit(event.getVarbitId()) || isGoatPitVarbit(event.getVarbitId()))
		{
			telegrabAvailability.refresh();
			tracker.refreshState();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
		{
			telegrabAvailability.refresh();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (tracker.isSpikePileInteraction(event.getId(), event.getMenuTarget()))
		{
			tracker.acknowledgeSpikePileReminder();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tracker.refreshState();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			tracker.clear();
			telegrabAvailability.clear();
		}
		else if (state == GameState.LOGGED_IN)
		{
			telegrabAvailability.refresh();
			tracker.refreshState();
		}
	}

	@Provides
	GoatHuntingPluginConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GoatHuntingPluginConfig.class);
	}

	private static boolean isGoatPitVarbit(int varbitId)
	{
		return varbitId == GoatHuntingIds.GOATS_IN_PIT_VARBIT || varbitId == GoatHuntingIds.SPIKES_PRESENT_VARBIT;
	}

	private static boolean isRunePouchVarbit(int varbitId)
	{
		switch (varbitId)
		{
			case VarbitID.RUNE_POUCH_TYPE_1:
			case VarbitID.RUNE_POUCH_TYPE_2:
			case VarbitID.RUNE_POUCH_TYPE_3:
			case VarbitID.RUNE_POUCH_TYPE_4:
			case VarbitID.RUNE_POUCH_TYPE_5:
			case VarbitID.RUNE_POUCH_TYPE_6:
			case VarbitID.RUNE_POUCH_QUANTITY_1:
			case VarbitID.RUNE_POUCH_QUANTITY_2:
			case VarbitID.RUNE_POUCH_QUANTITY_3:
			case VarbitID.RUNE_POUCH_QUANTITY_4:
			case VarbitID.RUNE_POUCH_QUANTITY_5:
			case VarbitID.RUNE_POUCH_QUANTITY_6:
				return true;
			default:
				return false;
		}
	}
}

