package com.goat;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

final class GoatHuntingIds
{
	static final int MIN_CAPACITY = 16;
	static final int MAX_CAPACITY = 24;
	static final int TELEGRAB_RANGE = 10;

	static final int GOAT_PIT_GOAT = NpcID.GOAT_PIT_GOAT;
	static final int GOATS_IN_PIT_VARBIT = VarbitID.GOAT_PIT_INPIT;
	static final int SPIKES_PRESENT_VARBIT = VarbitID.GOAT_PIT_SPIKES;

	static final String PIT_NAME_FRAGMENT = "goat pit";
	static final String GOAT_NAME_FRAGMENT = "goat";
	static final String SPIKE_NAME_FRAGMENT = "spike";
	static final String SPIKES_SUPPLY_NAME_FRAGMENT = "spikes supply";
	static final String PILE_NAME_FRAGMENT = "pile";

	private static final Set<Integer> GOAT_PIT_OBJECTS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ObjectID.GOAT_PIT,
		ObjectID.GOAT_PIT_MULTI_EMPTY,
		ObjectID.GOAT_PIT_MULTI_SPIKES,
		ObjectID.GOAT_PIT_MULTI_ONE,
		ObjectID.GOAT_PIT_MULTI_SOME,
		ObjectID.GOAT_PIT_MULTI_FULL
	)));

	private static final Set<Integer> AIR_RUNE_ITEMS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.AIRRUNE,
		ItemID.MISTRUNE,
		ItemID.DUSTRUNE,
		ItemID.SMOKERUNE
	)));

	private static final Set<Integer> AIR_STAFF_ITEMS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.STAFF_OF_AIR,
		ItemID.AIR_BATTLESTAFF,
		ItemID.MYSTIC_AIR_STAFF,
		ItemID.BR_AIR_STAFF,
		ItemID.MIST_BATTLESTAFF,
		ItemID.MYSTIC_MIST_BATTLESTAFF,
		ItemID.DUST_BATTLESTAFF,
		ItemID.MYSTIC_DUST_BATTLESTAFF,
		ItemID.SMOKE_BATTLESTAFF,
		ItemID.MYSTIC_SMOKE_BATTLESTAFF
	)));

	private GoatHuntingIds()
	{
		throw new AssertionError("constants holder");
	}

	static int capacityForHunterLevel(int hunterLevel)
	{
		if (hunterLevel >= 93)
		{
			return 24;
		}
		if (hunterLevel >= 85)
		{
			return 22;
		}
		if (hunterLevel >= 77)
		{
			return 20;
		}
		if (hunterLevel >= 70)
		{
			return 18;
		}
		return MIN_CAPACITY;
	}

	static boolean isGoatPitObject(int objectId)
	{
		return GOAT_PIT_OBJECTS.contains(objectId);
	}

	static boolean isSpikeSupplyObject(int objectId)
	{
		return objectId == ObjectID.GOAT_PIT_SPIKES;
	}

	static boolean isGoatPitGoat(int npcId)
	{
		return npcId == GOAT_PIT_GOAT;
	}

	static boolean isAirRune(int itemId)
	{
		return AIR_RUNE_ITEMS.contains(itemId);
	}

	static boolean isLawRune(int itemId)
	{
		return itemId == ItemID.LAWRUNE;
	}

	static boolean isAirStaff(int itemId)
	{
		return AIR_STAFF_ITEMS.contains(itemId);
	}
}

