package com.goat;

final class GoatPitState
{
	private final int count;
	private final boolean spiked;
	private final int capacity;

	GoatPitState(int count, boolean spiked, int capacity)
	{
		this.capacity = Math.max(GoatHuntingIds.MIN_CAPACITY, Math.min(GoatHuntingIds.MAX_CAPACITY, capacity));
		this.count = Math.max(0, Math.min(this.capacity, count));
		this.spiked = spiked;
	}

	int getCount()
	{
		return count;
	}

	int getCapacity()
	{
		return capacity;
	}

	boolean isFull()
	{
		return count >= capacity;
	}

	boolean needsSpikes()
	{
		return !spiked;
	}

	String label()
	{
		return count + " / " + capacity;
	}

	float fullness()
	{
		return capacity <= 0 ? 0 : (float) count / capacity;
	}
}

