package com.goat;

import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Skill;
import net.runelite.api.TileObject;
import net.runelite.client.util.Text;

@Singleton
class GoatHuntingTracker
{
	private final Map<Long, GameObject> pits = new LinkedHashMap<>();
	private final Map<Long, TileObject> spikePiles = new LinkedHashMap<>();
	private final Map<Integer, NPC> goats = new LinkedHashMap<>();

	@Inject
	private Client client;

	private Boolean lastNeedsSpikes;
	private boolean spikePileReminderAcknowledged = true;

	void onTileObjectSpawned(TileObject object)
	{
		if (object instanceof GameObject && isPit(object))
		{
			pits.put(object.getHash(), (GameObject) object);
		}
		if (isSpikePile(object))
		{
			spikePiles.put(object.getHash(), object);
		}
	}

	void onTileObjectDespawned(TileObject object)
	{
		if (object == null)
		{
			return;
		}
		pits.remove(object.getHash());
		spikePiles.remove(object.getHash());
	}

	void onNpcSpawned(NPC npc)
	{
		if (isGoat(npc))
		{
			goats.put(npc.getIndex(), npc);
		}
	}

	void onNpcDespawned(NPC npc)
	{
		if (npc != null)
		{
			goats.remove(npc.getIndex());
		}
	}

	void clear()
	{
		pits.clear();
		spikePiles.clear();
		goats.clear();
		resetStateMonitoring();
	}

	void refreshState()
	{
		boolean needsSpikes = readNeedsSpikes();
		if (lastNeedsSpikes == null)
		{
			lastNeedsSpikes = needsSpikes;
			spikePileReminderAcknowledged = !needsSpikes;
			return;
		}

		if (needsSpikes && !lastNeedsSpikes)
		{
			spikePileReminderAcknowledged = false;
		}
		else if (!needsSpikes)
		{
			spikePileReminderAcknowledged = true;
		}

		lastNeedsSpikes = needsSpikes;
	}

	void acknowledgeSpikePileReminder()
	{
		spikePileReminderAcknowledged = true;
	}

	boolean shouldShowSpikePileReminder()
	{
		return readNeedsSpikes() && !spikePileReminderAcknowledged && !pits.isEmpty() && !spikePiles.isEmpty();
	}

	boolean hasActivityContext()
	{
		return !pits.isEmpty() || !spikePiles.isEmpty();
	}

	Collection<GameObject> getPits()
	{
		return Collections.unmodifiableCollection(pits.values());
	}

	Collection<TileObject> getSpikePiles()
	{
		return Collections.unmodifiableCollection(spikePiles.values());
	}

	Collection<NPC> getGoats()
	{
		return Collections.unmodifiableCollection(goats.values());
	}

	GoatPitState stateOf(GameObject pit)
	{
		return new GoatPitState(
			client.getVarbitValue(GoatHuntingIds.GOATS_IN_PIT_VARBIT),
			client.getVarbitValue(GoatHuntingIds.SPIKES_PRESENT_VARBIT) != 0,
			GoatHuntingIds.capacityForHunterLevel(client.getRealSkillLevel(Skill.HUNTER))
		);
	}

	boolean isSpikePileInteraction(int objectId, String menuTarget)
	{
		if (GoatHuntingIds.isSpikeSupplyObject(objectId))
		{
			return true;
		}

		for (TileObject spikePile : spikePiles.values())
		{
			if (spikePile.getId() == objectId)
			{
				return true;
			}
		}
		return menuTarget != null && matchesSpikePileName(Text.removeTags(menuTarget));
	}

	static boolean matchesPitName(String name)
	{
		return contains(name, GoatHuntingIds.PIT_NAME_FRAGMENT);
	}

	static boolean matchesGoatName(String name)
	{
		return contains(name, GoatHuntingIds.GOAT_NAME_FRAGMENT);
	}

	static boolean matchesSpikePileName(String name)
	{
		String normalized = normalize(name);
		boolean hasPile = normalized.contains(GoatHuntingIds.PILE_NAME_FRAGMENT);
		return normalized.contains(GoatHuntingIds.SPIKES_SUPPLY_NAME_FRAGMENT)
			|| hasPile && normalized.contains(GoatHuntingIds.SPIKE_NAME_FRAGMENT);
	}

	private void resetStateMonitoring()
	{
		lastNeedsSpikes = null;
		spikePileReminderAcknowledged = true;
	}

	private boolean readNeedsSpikes()
	{
		return client.getVarbitValue(GoatHuntingIds.SPIKES_PRESENT_VARBIT) == 0;
	}

	private boolean isPit(TileObject object)
	{
		if (object == null)
		{
			return false;
		}
		return GoatHuntingIds.isGoatPitObject(object.getId()) || matchesPitName(objectName(object));
	}

	private boolean isSpikePile(TileObject object)
	{
		return object != null && (GoatHuntingIds.isSpikeSupplyObject(object.getId()) || matchesSpikePileName(objectName(object)));
	}

	private boolean isGoat(NPC npc)
	{
		return npc != null && (GoatHuntingIds.isGoatPitGoat(npc.getId()) || matchesGoatName(npc.getName()));
	}

	private String objectName(TileObject object)
	{
		ObjectComposition composition = client.getObjectDefinition(object.getId());
		if (composition == null)
		{
			return null;
		}
		return composition.getName();
	}

	private static boolean contains(String value, String fragment)
	{
		return normalize(value).contains(fragment);
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.toLowerCase(Locale.ROOT);
	}
}

