import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.awt.geom.Area;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class GoatHuntingOverlay extends Overlay
{
	private static final Stroke PIT_STROKE = new BasicStroke(2.0f);
	private static final Stroke SPIKE_PILE_STROKE = new BasicStroke(2.0f);
	private static final Stroke ARROW_STROKE = new BasicStroke(4.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final int GOAT_OUTLINE_WIDTH = 2;
	private static final int GOAT_OUTLINE_FEATHER = 0;
	private static final String REPLACE_SPIKES_TEXT = "REPLACE SPIKES";

	private final Client client;
	private final ModelOutlineRenderer modelOutlineRenderer;
	private final GoatHuntingPluginConfig config;
	private final GoatHuntingTracker tracker;
	private final TelegrabAvailability telegrabAvailability;

	@Inject
	GoatHuntingOverlay(
		Client client,
		ModelOutlineRenderer modelOutlineRenderer,
		GoatHuntingPluginConfig config,
		GoatHuntingTracker tracker,
		TelegrabAvailability telegrabAvailability)
	{
		this.client = client;
		this.modelOutlineRenderer = modelOutlineRenderer;
		this.config = config;
		this.tracker = tracker;
		this.telegrabAvailability = telegrabAvailability;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		WorldPoint playerLocation = player.getWorldLocation();
		renderPits(graphics, playerLocation);
		renderSpikePiles(graphics, playerLocation);
		renderTelegrabGoats(playerLocation);
		return null;
	}

	private void renderPits(Graphics2D graphics, WorldPoint playerLocation)
	{
		if (!config.drawPitOverlay() && !config.showPitCount() && !config.replaceSpikesAlert())
		{
			return;
		}

		for (GameObject pit : tracker.getPits())
		{
			if (!isNear(playerLocation, pit.getWorldLocation()))
			{
				continue;
			}
			renderPit(graphics, pit);
		}
	}

	private void renderPit(Graphics2D graphics, GameObject pit)
	{
		Area footprint = footprintOf(pit);
		if (footprint == null || footprint.isEmpty())
		{
			return;
		}

		GoatPitState state = tracker.stateOf(pit);
		Color pitColor = state.needsSpikes() ? config.pitFullColor() : fullnessColor(state);

		if (config.drawPitOverlay())
		{
			renderPitFootprint(graphics, footprint, pitColor);
		}

		if (config.replaceSpikesAlert() && state.needsSpikes())
		{
			renderPitText(graphics, pit, REPLACE_SPIKES_TEXT, config.pitFullColor());
		}
		else if (config.showPitCount())
		{
			renderPitText(graphics, pit, state.label(), pitColor);
		}
	}

	private void renderPitFootprint(Graphics2D graphics, Area footprint, Color pitColor)
	{
		Stroke originalStroke = graphics.getStroke();

		graphics.setColor(pitColor);
		graphics.setStroke(PIT_STROKE);
		graphics.draw(footprint);
		graphics.setStroke(originalStroke);
	}

	private void renderPitText(Graphics2D graphics, GameObject pit, String text, Color color)
	{
		Point at = pit.getCanvasTextLocation(graphics, text, 0);
		if (at != null)
		{
			OverlayUtil.renderTextLocation(graphics, at, text, color);
		}
	}

	private void renderSpikePiles(Graphics2D graphics, WorldPoint playerLocation)
	{
		if (!config.spikePileReminder() || !tracker.shouldShowSpikePileReminder())
		{
			return;
		}

		for (TileObject spikePile : tracker.getSpikePiles())
		{
			if (!isNear(playerLocation, spikePile.getWorldLocation()))
			{
				continue;
			}
			renderSpikePile(graphics, spikePile);
		}
	}

	private void renderSpikePile(Graphics2D graphics, TileObject spikePile)
	{
		Color color = config.spikePileColor();
		Polygon poly = spikePile.getCanvasTilePoly();
		if (poly != null)
		{
			OverlayUtil.renderPolygon(graphics, poly, color, withAlpha(color, 35), SPIKE_PILE_STROKE);
		}

		if (arrowVisible())
		{
			Point point = spikePile.getCanvasLocation(120);
			if (point != null)
			{
				renderArrow(graphics, point, color);
			}
		}
	}

	private void renderTelegrabGoats(WorldPoint playerLocation)
	{
		if (!config.telegrabGoats() || !telegrabAvailability.isAvailable() || !tracker.hasActivityContext())
		{
			return;
		}

		for (NPC goat : tracker.getGoats())
		{
			WorldPoint goatLocation = goat.getWorldLocation();
			if (!isNear(playerLocation, goatLocation)
				|| playerLocation.distanceTo(goatLocation) > config.telegrabRange())
			{
				continue;
			}
			renderGoat(goat);
		}
	}

	private void renderGoat(NPC goat)
	{
		modelOutlineRenderer.drawOutline(goat, GOAT_OUTLINE_WIDTH, config.telegrabGoatColor(), GOAT_OUTLINE_FEATHER);
	}

	private void renderArrow(Graphics2D graphics, Point point, Color color)
	{
		int offset = (client.getGameCycle() / 5) % 2 == 0 ? 0 : 5;
		int x = point.getX();
		int tipY = point.getY() - 8 + offset;
		int topY = tipY - 34;

		Stroke originalStroke = graphics.getStroke();
		graphics.setStroke(ARROW_STROKE);
		graphics.setColor(Color.BLACK);
		graphics.drawLine(x + 1, topY + 1, x + 1, tipY + 1);
		graphics.setColor(color);
		graphics.drawLine(x, topY, x, tipY);

		Polygon head = new Polygon(
			new int[]{x - 9, x + 9, x},
			new int[]{tipY - 11, tipY - 11, tipY + 6},
			3
		);
		graphics.setColor(Color.BLACK);
		graphics.fillPolygon(head);
		head.translate(0, -1);
		graphics.setColor(color);
		graphics.fillPolygon(head);
		graphics.setStroke(originalStroke);
	}

	private Area footprintOf(GameObject pit)
	{
		Point min = pit.getSceneMinLocation();
		Point max = pit.getSceneMaxLocation();
		if (min == null || max == null)
		{
			return null;
		}

		Area area = new Area();
		for (int x = min.getX(); x <= max.getX(); x++)
		{
			for (int y = min.getY(); y <= max.getY(); y++)
			{
				LocalPoint tile = LocalPoint.fromScene(x, y, pit.getWorldView());
				Polygon poly = Perspective.getCanvasTilePoly(client, tile);
				if (poly != null)
				{
					area.add(new Area(poly));
				}
			}
		}
		return area;
	}

	private boolean isNear(WorldPoint playerLocation, WorldPoint worldPoint)
	{
		return worldPoint != null && playerLocation.distanceTo(worldPoint) <= config.maxDrawDistance();
	}

	private boolean arrowVisible()
	{
		return (client.getGameCycle() / 12) % 2 == 0;
	}

	private Color fullnessColor(GoatPitState state)
	{
		return lerp(config.pitEmptyColor(), config.pitFullColor(), state.fullness());
	}

	private static Color lerp(Color from, Color to, float fraction)
	{
		float f = Math.max(0.0f, Math.min(1.0f, fraction));
		int r = Math.round(from.getRed() + (to.getRed() - from.getRed()) * f);
		int g = Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * f);
		int b = Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * f);
		int a = Math.round(from.getAlpha() + (to.getAlpha() - from.getAlpha()) * f);
		return new Color(r, g, b, a);
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}
}
